// Bottleneck 1: Poor Spatial Locality (Array of Structures)
struct Particle { float x, y, mass; };
Particle p[1000];

// Optimization: Structure of Arrays (SoA) for better cache use
float X[1000], Y[1000], Mass[1000];

// Bottleneck 2: Excessive Dynamic Memory Allocation
// Avoid repeated heap management in hot loops
// Instead of: T* obj = new T();

// Optimization: Use Placement New on pre-allocated buffer
char arena[1024];
T* obj_ptr = new (arena) T();
// Manual destructor call needed for complex objects

// Bottleneck 3: Function Call Overhead (Small functions)
// Use compiler optimization hints
inline int squared(int x) {
    return x * x;
}

// Bottleneck 4: Thread Synchronization Contention
// Bottleneck: Heavy Mutex locking for simple updates
// std::lock_guard<std::mutex> lock(m); counter++;

// Optimization: Use lock-free atomic primitives
std::atomic<int> thread_counter{0};
thread_counter.fetch_add(1);

// Bottleneck 5: Vectorization Hinting (SIMD potential)
// Inform the compiler loop is safe for parallel execution
#pragma GCC optimize("O3")
#pragma GCC ivdep // Ignore vector dependency
for (int i = 0; i < N; ++i) {
    C[i] = A[i] * 2.0f;
}
